// CPersistTraits<SRecord54>::TransferBinaryIn: fast copy out of the chunk when 0x54 bytes remain, the
// overflow reader otherwise, nothing when the advanced position leaves [0, 0x7FFFFFFF].
#ifdef _MSC_VER
