    SRecord54 rec;
    traits.TransferBinaryIn(&s, &rec);
    bool ok = rec.Bytes[0] == 0 && rec.Bytes[0x53] == 0x53 && s.Cursor == chunk + 0x54
        && s.RemainingInSourceChunk == 0x0C && s.ReadPosition == 0x64 && g_overflowCalls == 0;
